@Injectable()
export class DetranLegacyAuthContextGuard implements CanActivate {
  constructor(
    private readonly reflector: Reflector,
    private readonly inner: LegacyAuthContextGuard,
  ) {}

  canActivate(context: ExecutionContext): boolean | Promise<boolean> {
    const isPublic = this.reflector.getAllAndOverride<boolean | undefined>(
      DETRAN_PUBLIC_METADATA_KEY,
      [context.getHandler(), context.getClass()],
    );
    if (isPublic) return true;
    const request = context
      .switchToHttp()
      .getRequest<{ path?: string; url?: string }>();
    const path = request.path ?? request.url ?? '';
    if (/^\/(healthz|readyz|metrics|info)(\?|$)/.test(path)) return true;
    return this.inner.canActivate(context);
  }
}

@Injectable()
export class DetranStynxAuthContextGuard implements CanActivate {
  constructor(
    private readonly reflector: Reflector,
    private readonly inner: StynxAuthGuard,
  ) {}

  canActivate(context: ExecutionContext): boolean | Promise<boolean> {
    const isPublic = this.reflector.getAllAndOverride<boolean | undefined>(
      DETRAN_PUBLIC_METADATA_KEY,
      [context.getHandler(), context.getClass()],
    );
    if (isPublic) return true;
    const request = context
      .switchToHttp()
      .getRequest<{ path?: string; url?: string }>();
    const path = request.path ?? request.url ?? '';
    if (/^\/(healthz|readyz|metrics|info)(\?|$)/.test(path)) return true;
    return this.inner.canActivate(context);
  }
}

@Injectable()
class DetranDatabaseBinder implements OnModuleInit {
  constructor(
    private readonly database: Database,
    private readonly requestContext: RequestContext,
    private readonly requestContextMutator: RequestContextMutator,
  ) {}

  onModuleInit(): void {
    detranAuditSink.bindDatabase(this.database);
    detranPostgresReadiness.bindDatabase(this.database);
    detranPipelineSqlExecutor.bindDatabase(this.database);
    detranPersistentPipelineStore.bindRequestContext(
      this.requestContext,
      this.requestContextMutator,
    );
  }
}

@Module({})
export class AppModule {
  static forRoot(): DynamicModule {
    const local = isLocalRuntimeProfile(detranRuntimeProfile());
    const authImports = local
      ? [
          LegacyStynxAuthModule.forRoot({
            tokenVerifier: detranTokenVerifier(),
            tenantResolver: new DetranTenantResolver(),
            tenantEntitlementPolicy: new DetranTenantEntitlementPolicy(),
          }),
        ]
      : [
          StynxSessionsModule.forRoot(detranSessionsOptions()),
          FullStynxAuthModule.forRoot(detranFullAuthOptions()),
        ];
    const authProviders = local
      ? [
          DetranLegacyAuthContextGuard,
          {
            provide: APP_GUARD,
            useExisting: DetranLegacyAuthContextGuard,
          },
        ]
      : [
          DetranStynxAuthContextGuard,
          DetranSessionStrongFactorGuard,
          DetranSingleSessionInterceptor,
          DetranSessionReadinessBinder,
          DetranClinicalTrustReadinessBinder,
          PadesSigningHttpAdapter,
          {
            provide: DetranSessionReadiness,
            useValue: detranSessionReadiness,
          },
          {
            provide: DetranClinicalTrustReadiness,
            useValue: detranClinicalTrustReadiness,
          },
          {
            provide: APP_GUARD,
            useExisting: DetranStynxAuthContextGuard,
          },
          {
            provide: APP_GUARD,
            useExisting: DetranSessionStrongFactorGuard,
          },
          {
            provide: APP_INTERCEPTOR,
            useExisting: DetranSingleSessionInterceptor,
          },
        ];
    return {
      module: AppModule,
      imports: [
        StynxLoggingModule.forRoot({
          level: process.env.LOG_LEVEL ?? 'info',
          redactPaths: ['authorization', 'cookie', 'set-cookie'],
        }),
        StynxDataModule.forRoot(detranDataOptions()),
        ...authImports,
        StynxAuthorizationModule.forRoot({
          policyEvaluator: new DetranPolicyEvaluator(),
        }),
        StynxTenancyModule.forRoot({}),
        StynxAuditModule.forRoot({ sink: detranAuditSink }),
        StynxStorageModule.forRoot(detranStorageOptions()),
        StynxPlatformPipelineModule.forRoot(detranPipelineOptions()),
        StynxHealthModule.forRoot(
          detranHealthOptions(
            detranPostgresReadiness,
            local ? undefined : detranSessionReadiness,
          ),
          local ? [] : [detranClinicalTrustReadiness],
        ),
        ClinicalNetworkModule,
        PatientsModule,
        EncountersModule,
        BiometricsModule,
        BillingModule,
        ExamsModule,
        ClinicalControlsModule,
        InconsistenciesModule,
        JuntasModule,
        OperationalControlsModule,
        ClinicalReportsModule,
        ProcessBlocksModule,
        TelehealthModule,
        ToxicologyModule,
        SchedulingModule,
        RestrictionsModule,
        RetentionModule,
        ComplaintsModule,
        // Infractions scope (TEAT/RAIT): generated CRUD modules plus the
        // handwritten AIT lifecycle commands (WP-T0).
        NormativeModule,
        ParameterModule,
        AitModule,
        MeasuresModule,
        AlcoholModule,
        RaitCaseModule,
        RaitWorklistModule,
        RaitSessionModule,
        AgencyModule,
        FieldModule,
        SnapshotsModule,
        EvidenceModule,
        OfflineSyncModule,
        DetranErrorFilterModule,
        // Speed meters stay behind the `teat.speed_meters` flag (steering H.54:
        // the agency does not operate meters today).
        ...(detranFeatureFlagSet().flags['teat.speed_meters']?.default === true
          ? [SpeedModule]
          : []),
      ],
      controllers: [
        PecProcessParametersController,
        PecRenachProcessController,
        PecRenachTransmissionController,
        PecToxicologyInboundController,
        PecSefazController,
        PecAuditQueryController,
        PecUserAdminController,
        PecCognitoAdminController,
      ],
      providers: [
        DetranDatabaseBinder,
        ...authProviders,
        DetranPolicyGuard,
        PecProcessParametersService,
        PecRenachProcessService,
        PecRenachTransmissionService,
        PecToxicologyInboundService,
        PecSefazService,
        PecAuditQueryService,
        PecUserAdminService,
        RenachWebhookGuard,
        {
          provide: PEC_RENACH_PORT,
          useFactory: () => createSenatranAdapter().ports.renach,
        },
        {
          provide: PEC_SEFAZ_PORT,
          useFactory: () => {
            const provider =
              process.env.DETRAN_SEFAZ_PROVIDER ?? (local ? 'mock' : 'real');
            if (provider !== 'mock' && provider !== 'real') {
              throw new Error('DETRAN_SEFAZ_PROVIDER must be mock or real');
            }
            const baseUrl =
              provider === 'mock'
                ? (process.env.DETRAN_SEFAZ_MOCK_BASE_URL ??
                  'http://localhost:3999')
                : process.env.DETRAN_SEFAZ_REAL_BASE_URL;
            if (!baseUrl) {
              throw new Error(
                'DETRAN_SEFAZ_REAL_BASE_URL is required for the real provider',
              );
            }
            return new SefazHttpAdapter({
              baseUrl,
              pathPrefix: provider === 'mock' ? '/mock' : '',
              timeoutMs: Number(process.env.DETRAN_SEFAZ_TIMEOUT_MS ?? '10000'),
            });
          },
        },
        {
          provide: PecCognitoAdminService,
          useFactory: () =>
            new PecCognitoAdminService(
              new CognitoIdentityProviderClient({
                region: process.env.DETRAN_COGNITO_REGION ?? 'sa-east-1',
              }),
              process.env.DETRAN_COGNITO_USER_POOL_ID ?? '',
            ),
        },
        { provide: DetranPersistedAuditSink, useValue: detranAuditSink },
        { provide: DetranPostgresReadiness, useValue: detranPostgresReadiness },
        DetranPolicyErrorGuard,
        { provide: APP_GUARD, useExisting: DetranPolicyErrorGuard },
        RaitTransactionalAuditInterceptor,
        {
          provide: APP_INTERCEPTOR,
          useExisting: RaitTransactionalAuditInterceptor,
        },
      ],
    };
  }
}

import type { ArgumentsHost } from '@nestjs/common';
import { HttpException } from '@nestjs/common';
import { DetranError } from '@detran/shared';
import { describe, expect, it, vi } from 'vitest';

type FilterConstructor = new () => {
  catch(exception: unknown, host: ArgumentsHost): void;
};

const modulePath = './detran-error.filter.js';

async function subject() {
  const module = (await import(modulePath)) as {
    DetranErrorFilter: FilterConstructor;
  };
  return new module.DetranErrorFilter();
}

function host() {
  const json = vi.fn();
  const status = vi.fn(() => ({ json }));
  return {
    argumentsHost: {
      switchToHttp: () => ({
        getResponse: () => ({ status }),
        getRequest: () => ({}),
        getNext: () => undefined,
      }),
      getArgs: () => [],
      getArgByIndex: () => undefined,
      switchToRpc: () => ({
        getContext: () => undefined,
        getData: () => undefined,
      }),
      switchToWs: () => ({
        getClient: () => undefined,
        getData: () => undefined,
        getPattern: () => undefined,
      }),
      getType: () => 'http',
    } as unknown as ArgumentsHost,
    json,
    status,
  };
}

describe('CTG-0001 §10.9 — envelope HTTP local de DetranError', () => {
  it('serializa todos os campos estáveis, incluindo status, messageKey e requestId', async () => {
    const filter = await subject();
    const response = host();
    filter.catch(
      new DetranError('RAIT.FORBIDDEN_ACTION', {
        status: 403,
        messageKey: 'rait.errors.forbidden_action',
        message: 'Ação não permitida.',
        requestId: 'req-r7-filter',
        context: { action: 'admit' },
      }),
      response.argumentsHost,
    );

    expect(response.status).toHaveBeenCalledWith(403);
    expect(response.json).toHaveBeenCalledWith({
      code: 'RAIT.FORBIDDEN_ACTION',
      status: 403,
      message: 'Ação não permitida.',
      messageKey: 'rait.errors.forbidden_action',
      requestId: 'req-r7-filter',
      context: { action: 'admit' },
    });
  });

  it('preserva campos opcionais de modo determinístico sem inventar requestId', async () => {
    const filter = await subject();
    const response = host();
    filter.catch(
      new DetranError('RAIT.VALIDATION_FAILED', {
        status: 400,
        messageKey: 'rait.errors.validation_failed',
        message: 'Entrada inválida.',
      }),
      response.argumentsHost,
    );

    expect(response.json).toHaveBeenCalledWith({
      code: 'RAIT.VALIDATION_FAILED',
      status: 400,
      message: 'Entrada inválida.',
      messageKey: 'rait.errors.validation_failed',
      context: {},
    });
  });

  it('é restrito a DetranError e deixa HttpException para o filtro STYNX', async () => {
    const filter = await subject();
    const response = host();
    const exception = new HttpException({ code: 'NON_RAIT' }, 409);

    expect(() => filter.catch(exception, response.argumentsHost)).toThrow(
      exception,
    );
    expect(response.status).not.toHaveBeenCalled();
  });
});

import type { ArgumentsHost, ExceptionFilter } from '@nestjs/common';
import { Catch, HttpException, Injectable, Module } from '@nestjs/common';
import { ApplicationConfig } from '@nestjs/core';

import { DetranError } from '@detran/shared';

const body = (exception: DetranError) => ({
  code: exception.code,
  status: exception.status,
  message: exception.message,
  messageKey: exception.messageKey,
  ...(exception.requestId ? { requestId: exception.requestId } : {}),
  context: exception.context,
});

export const asDetranHttpException = (exception: DetranError): HttpException =>
  new HttpException(body(exception), exception.status);

@Catch(DetranError)
export class DetranErrorFilter implements ExceptionFilter<DetranError> {
  catch(exception: DetranError, host: ArgumentsHost): void {
    if (!(exception instanceof DetranError)) throw exception;
    const response = host.switchToHttp().getResponse<{
      status(code: number): { json(body: Record<string, unknown>): void };
    }>();
    response.status(exception.status).json(body(exception));
  }
}

@Injectable()
class DetranErrorFilterRegistrar {
  constructor(applicationConfig: ApplicationConfig, filter: DetranErrorFilter) {
    applicationConfig.addGlobalFilter(filter);
  }
}

@Module({
  providers: [DetranErrorFilter, DetranErrorFilterRegistrar],
})
export class DetranErrorFilterModule {}

import type { ExecutionContext } from '@nestjs/common';
import { ForbiddenException, HttpException } from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { Action, DetranPolicyGuard, Resource } from '@detran/shared';
import { describe, expect, it, vi } from 'vitest';

type GuardConstructor = new (
  delegate: DetranPolicyGuard,
  reflector: Reflector,
) => { canActivate(context: ExecutionContext): boolean };

const modulePath = './detran-policy-error.guard.js';

@Resource('inf:rait-case')
class RaitController {
  @Action('admit')
  admit(): void {}
}

@Resource('inf:ait')
class OtherController {
  @Action('finalize')
  finalize(): void {}
}

async function subject(delegate: { canActivate: ReturnType<typeof vi.fn> }) {
  const module = (await import(modulePath)) as {
    DetranPolicyErrorGuard: GuardConstructor;
  };
  return new module.DetranPolicyErrorGuard(
    delegate as unknown as DetranPolicyGuard,
    new Reflector(),
  );
}

function context(
  controller: object,
  handler: (...args: never[]) => unknown,
  withPrincipal = true,
): ExecutionContext {
  return {
    getClass: () => controller,
    getHandler: () => handler,
    switchToHttp: () => ({
      getRequest: () => ({
        ...(withPrincipal
          ? {
              principal: {
                id: '00000000-0000-4000-8000-0000b0000001',
                roles: ['rait-secretary'],
                permissions: [],
              },
            }
          : {}),
      }),
      getResponse: () => ({}),
      getNext: () => undefined,
    }),
    getArgs: () => [],
    getArgByIndex: () => undefined,
    switchToRpc: () => ({
      getContext: () => undefined,
      getData: () => undefined,
    }),
    switchToWs: () => ({
      getClient: () => undefined,
      getData: () => undefined,
      getPattern: () => undefined,
    }),
    getType: () => 'http',
  } as unknown as ExecutionContext;
}

describe('CTG-0001 §10.10 — adaptação local de negação da política RAIT', () => {
  it('dado papel negado em RAIT quando a guarda adapta então preserva 403 e envelope estável', async () => {
    const delegate = {
      canActivate: vi.fn(() => {
        throw new ForbiddenException('Access denied');
      }),
    };
    const guard = await subject(delegate);

    let thrown: unknown;
    try {
      guard.canActivate(
        context(RaitController, RaitController.prototype.admit),
      );
    } catch (error) {
      thrown = error;
    }

    expect(thrown).toBeInstanceOf(HttpException);
    expect((thrown as HttpException).getStatus()).toBe(403);
    expect((thrown as HttpException).getResponse()).toMatchObject({
      code: 'RAIT.FORBIDDEN_ACTION',
      status: 403,
      messageKey: 'rait.errors.forbidden_action',
      context: {
        resource: 'inf:rait-case',
        action: 'admit',
        roles: ['rait-secretary'],
      },
    });
  });

  it('dado papel permitido quando a guarda delegada autoriza então preserva true', async () => {
    const delegate = { canActivate: vi.fn(() => true) };
    const guard = await subject(delegate);
    const execution = context(RaitController, RaitController.prototype.admit);

    expect(guard.canActivate(execution)).toBe(true);
    expect(delegate.canActivate).toHaveBeenCalledWith(execution);
  });

  it('dado recurso não RAIT negado quando a guarda adapta então preserva a exceção original', async () => {
    const denial = new ForbiddenException('Access denied outside RAIT');
    const delegate = {
      canActivate: vi.fn(() => {
        throw denial;
      }),
    };
    const guard = await subject(delegate);

    expect(() =>
      guard.canActivate(
        context(OtherController, OtherController.prototype.finalize),
      ),
    ).toThrow(denial);
  });

  it('dado exceção alheia quando a guarda delegada falha então preserva a mesma exceção', async () => {
    const failure = new Error('foreign-policy-failure');
    const delegate = {
      canActivate: vi.fn(() => {
        throw failure;
      }),
    };
    const guard = await subject(delegate);

    expect(() =>
      guard.canActivate(
        context(RaitController, RaitController.prototype.admit),
      ),
    ).toThrow(failure);
  });

  it('dado principal ausente quando RAIT é protegido então a negação continua fechada', async () => {
    const denial = new ForbiddenException(
      'Missing authenticated DETRAN principal',
    );
    const delegate = {
      canActivate: vi.fn(() => {
        throw denial;
      }),
    };
    const guard = await subject(delegate);

    expect(() =>
      guard.canActivate(
        context(RaitController, RaitController.prototype.admit, false),
      ),
    ).toThrow(denial);
  });
});

import type { CanActivate, ExecutionContext } from '@nestjs/common';
import { ForbiddenException, Injectable } from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { getPrincipalFromRequest, type RequestLike } from '@stynx-nyx/backend';

import {
  DETRAN_ACTION_METADATA_KEY,
  DETRAN_RESOURCE_METADATA_KEY,
  DetranError,
  DetranPolicyGuard,
} from '@detran/shared';

import { asDetranHttpException } from './detran-error.filter.js';

@Injectable()
export class DetranPolicyErrorGuard implements CanActivate {
  constructor(
    private readonly delegate: DetranPolicyGuard,
    private readonly reflector: Reflector,
  ) {}

  canActivate(context: ExecutionContext): boolean {
    try {
      return this.delegate.canActivate(context);
    } catch (error) {
      if (error instanceof ForbiddenException) {
        const resource = this.reflector.getAllAndOverride<string | undefined>(
          DETRAN_RESOURCE_METADATA_KEY,
          [context.getHandler(), context.getClass()],
        );
        const action = this.reflector.get<string | undefined>(
          DETRAN_ACTION_METADATA_KEY,
          context.getHandler(),
        );
        const principal = getPrincipalFromRequest(
          context.switchToHttp().getRequest<RequestLike>(),
        );
        if (resource?.startsWith('inf:rait-') && action && principal)
          throw asDetranHttpException(
            new DetranError('RAIT.FORBIDDEN_ACTION', {
              status: 403,
              messageKey: 'rait.errors.forbidden_action',
              message: 'Ação não permitida para o papel autenticado.',
              context: { resource, action, roles: principal.roles },
            }),
          );
      }
      throw error;
    }
  }
}

import type { CallHandler, ExecutionContext } from '@nestjs/common';
import { AuditInterceptor } from '@stynx-nyx/backend';
import { firstValueFrom, of } from 'rxjs';
import { describe, expect, it, vi } from 'vitest';

import { RaitCaseCommandsController } from '@detran/inf-rait-case';

import { PecSefazController } from './pec-sefaz.controller.js';

type InterceptorConstructor = new (delegate: AuditInterceptor) => {
  intercept(context: ExecutionContext, next: CallHandler): unknown;
};

const modulePath = './rait-transactional-audit.interceptor.js';

async function subject(delegate: { intercept: ReturnType<typeof vi.fn> }) {
  const module = (await import(modulePath)) as {
    RaitTransactionalAuditInterceptor: InterceptorConstructor;
  };
  return new module.RaitTransactionalAuditInterceptor(delegate as never);
}

function executionContext(
  controller: object,
  handler: (...args: never[]) => unknown,
  url: string,
): ExecutionContext {
  return {
    getClass: () => controller,
    getHandler: () => handler,
    switchToHttp: () => ({
      getRequest: () => ({ url }),
      getResponse: () => ({}),
      getNext: () => undefined,
    }),
    getArgs: () => [],
    getArgByIndex: () => undefined,
    switchToRpc: () => ({
      getContext: () => undefined,
      getData: () => undefined,
    }),
    switchToWs: () => ({
      getClient: () => undefined,
      getData: () => undefined,
      getPattern: () => undefined,
    }),
    getType: () => 'http',
  } as unknown as ExecutionContext;
}

describe('CTG-0001 §10.9 — seleção local de auditoria transacional', () => {
  it('não executa o AuditInterceptor STYNX depois de um command handler RAIT concreto', async () => {
    const delegate = { intercept: vi.fn(() => of('stynx')) };
    const interceptor = await subject(delegate);
    const next = { handle: vi.fn(() => of('domain-transaction')) };

    const result = await firstValueFrom(
      interceptor.intercept(
        executionContext(
          RaitCaseCommandsController,
          RaitCaseCommandsController.prototype.admit,
          '/v1/inf/rait/cases/case/commands/admit',
        ),
        next,
      ) as ReturnType<typeof of>,
    );

    expect(result).toBe('domain-transaction');
    expect(next.handle).toHaveBeenCalledOnce();
    expect(delegate.intercept).not.toHaveBeenCalled();
  });

  it('delega handler não RAIT mesmo quando a URL tenta simular o prefixo RAIT', async () => {
    const delegate = {
      intercept: vi.fn((_context, next: CallHandler) => next.handle()),
    };
    const interceptor = await subject(delegate);
    const next = { handle: vi.fn(() => of('preserved-stynx-audit')) };
    const context = executionContext(
      PecSefazController,
      PecSefazController.prototype.validatePayment,
      '/v1/inf/rait/cases/spoof/commands/admit',
    );

    await expect(
      firstValueFrom(
        interceptor.intercept(context, next) as ReturnType<typeof of>,
      ),
    ).resolves.toBe('preserved-stynx-audit');
    expect(delegate.intercept).toHaveBeenCalledOnce();
    expect(delegate.intercept).toHaveBeenCalledWith(context, next);
  });

  it('seleciona por identidade do handler, não por URL controlada pelo cliente', async () => {
    const delegate = { intercept: vi.fn(() => of('stynx')) };
    const interceptor = await subject(delegate);
    const next = { handle: vi.fn(() => of('domain-transaction')) };

    await expect(
      firstValueFrom(
        interceptor.intercept(
          executionContext(
            RaitCaseCommandsController,
            RaitCaseCommandsController.prototype.remit,
            '/unrelated-client-url',
          ),
          next,
        ) as ReturnType<typeof of>,
      ),
    ).resolves.toBe('domain-transaction');
    expect(delegate.intercept).not.toHaveBeenCalled();
  });
});

import type {
  CallHandler,
  ExecutionContext,
  NestInterceptor,
} from '@nestjs/common';
import { Injectable } from '@nestjs/common';
import { AuditInterceptor } from '@stynx-nyx/backend';
import { DetranError } from '@detran/shared';
import { catchError, type Observable, throwError } from 'rxjs';

import {
  RaitCaseCommandsController,
  RaitInquiryCommandsController,
} from '@detran/inf-rait-case';

import { asDetranHttpException } from './detran-error.filter.js';

type Handler = (...args: never[]) => unknown;

const TRANSACTIONALLY_AUDITED = new Map<object, ReadonlySet<Handler>>([
  [
    RaitCaseCommandsController,
    new Set<Handler>([
      RaitCaseCommandsController.prototype.admit,
      RaitCaseCommandsController.prototype.nonAdmission,
      RaitCaseCommandsController.prototype.remit,
      RaitCaseCommandsController.prototype.receive,
      RaitCaseCommandsController.prototype.ready,
      RaitCaseCommandsController.prototype.decide,
      RaitCaseCommandsController.prototype.returnDraft,
      RaitCaseCommandsController.prototype.withdraw,
      RaitCaseCommandsController.prototype.redirect,
      RaitCaseCommandsController.prototype.resolvePending,
      RaitCaseCommandsController.prototype.claimNext,
    ]),
  ],
  [
    RaitInquiryCommandsController,
    new Set<Handler>([
      RaitInquiryCommandsController.prototype.answer,
      RaitInquiryCommandsController.prototype.extend,
      RaitInquiryCommandsController.prototype.expire,
    ]),
  ],
]);

@Injectable()
export class RaitTransactionalAuditInterceptor implements NestInterceptor {
  constructor(private readonly delegate: AuditInterceptor) {}

  intercept(context: ExecutionContext, next: CallHandler): Observable<unknown> {
    const handlers = TRANSACTIONALLY_AUDITED.get(context.getClass());
    if (handlers?.has(context.getHandler() as Handler))
      return next
        .handle()
        .pipe(
          catchError((error: unknown) =>
            throwError(() =>
              error instanceof DetranError
                ? asDetranHttpException(error)
                : error,
            ),
          ),
        );
    return this.delegate.intercept(context, next);
  }
}

