  "type": "object",
  "required": ["schemaVersion", "id", "module", "database"],
  "properties": {
    "schemaVersion": {
      "const": "1.0.0"
    },
    "id": {
      "type": "string",
      "pattern": "^BP-[A-Z0-9-]+$"
    },
    "module": {
      "type": "object",
      "required": ["name", "namespace", "version"],
      "properties": {
        "name": {
          "type": "string"
        },
        "namespace": {
          "type": "string",
          "pattern": "^[a-z][a-z0-9-]*$"
        },
        "version": {
          "type": "string"
        },
